import {watchlist,removeSaved,esc,ago} from './research-store.mjs';
const items=document.getElementById('items'),count=document.getElementById('count');
function draw(){const saved=watchlist();count.textContent=`Watchlist · ${saved.length}`;items.innerHTML=saved.length?saved.map(item=>`<article class="saved-item"><div><span class="kicker">${esc(item.type)}</span><h2>${esc(item.title)}</h2><p>${esc(item.subtitle||'Saved research item')} · saved ${esc(ago(item.savedAt))}</p></div><div class="saved-item-actions"><a href="${esc(item.href)}">Open ↗</a><button type="button" data-remove="${esc(item.id)}" data-type="${esc(item.type)}">Remove</button></div></article>`).join(''):'<div class="empty-workspace"><strong>Your research queue is empty.</strong>Open a narrative from Tweet and save it here for follow-up.<br><br><a href="./narratives.html">Browse incoming narratives ↗</a></div>'}
items.onclick=e=>{const button=e.target.closest('[data-remove]');if(button){removeSaved(button.dataset.type,button.dataset.remove);draw()}};draw();
